import{_ as s,o as e,c as o,a2 as t}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"랜덤 추가 로스터","description":"","frontmatter":{},"headers":[],"relativePath":"world/Random-Cast-Roster.md","filePath":"world/Random-Cast-Roster.md"}'),n={name:"world/Random-Cast-Roster.md"};function i(r,a,l,p,d,c){return e(),o("div",null,[...a[0]||(a[0]=[t(`<h1 id="랜덤-추가-로스터" tabindex="-1">랜덤 추가 로스터 <a class="header-anchor" href="#랜덤-추가-로스터" aria-label="Permalink to &quot;랜덤 추가 로스터&quot;">​</a></h1><p>이름 있는 412명 총람을 지우지 않는다. 이 페이지는 <strong>추가로 굴릴 수 있는 100명</strong>이다. 한 세력에 몰지 않았고, 생업 일곱에 흩뿌렸다. 기계 정본은 <a href="name-pools/roster-100.json">roster-100.json</a>이다.</p><p>생성은 Windows <code>desktop-bo514et</code>에서 돌렸다. Hugging Face 캐시는 <code>E:\\git\\huggingface</code>만 쓴다. parquet는 <code>E:\\git\\huggingface\\datasets\\nvidia\\Nemotron-Personas-Korea\\train-00000.parquet</code>. 생성기: <code>tools/cast/generate_nemotron_roster.py</code>. 시드 <code>90421</code>.</p><p>Nemotron 행에는 이름이 없다. 인구·직업·병역·페르소나 문장만 있다. 성명은 <a href="name-pools/surnames.json">성씨 풀</a>, <a href="name-pools/given-male.json">남성 이름</a>, <a href="name-pools/given-female.json">여성 이름</a>에서 붙이고, 명문만 <a href="/world/Hangnyeol-and-Bon-gwan.html">본관과 항렬</a>을 이름 앞글자에 덮어쓴다.</p><p>일본 ESC 스페이스와 NGC <code>ko_KR</code> 카탈로그는 <strong>역사 인물 생성기가 아니다</strong>. 전자는 현대 페르소나 클러스터 리포트, 후자는 로그인 벽이 있는 데이터셋 카드다.</p><h2 id="한-명-굴리기" tabindex="-1">한 명 굴리기 <a class="header-anchor" href="#한-명-굴리기" aria-label="Permalink to &quot;한 명 굴리기&quot;">​</a></h2><p>저장소 루트에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PY&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import json, random</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">from pathlib import Path</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">roster = json.loads(Path(&#39;docs/game-logic/name-pools/roster-100.json&#39;).read_text())[&#39;people&#39;]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">p = random.choice(roster)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">print(p[&#39;성명&#39;], p[&#39;생업&#39;], p[&#39;소속&#39;], p[&#39;징집 이력&#39;], p.get(&#39;본관&#39;) or &#39;-&#39;)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PY</span></span></code></pre></div><p>결정론이 필요하면 캠페인 시드의 인물 스트림으로 <code>id</code>를 고른다. 같은 <code>source_uuid</code>를 두 번 쓰지 않는다.</p><h2 id="분포-시드-90421" tabindex="-1">분포 (시드 90421) <a class="header-anchor" href="#분포-시드-90421" aria-label="Permalink to &quot;분포 (시드 90421)&quot;">​</a></h2><ul><li>16국에 분산. 한 국 최대 8명.</li><li>생업: 전령 17, 의무원 17, 기록관 17, 순찰대 16, 정비사 16, 물류상 15, 탐사원 2.</li><li>항렬 적용 7명. 이주민 회랑 이름은 이 JSON에 넣지 않는다. 회랑 시드는 <a href="/world/Diaspora-Corridors.html">이주민 회랑</a>.</li></ul><p>칸은 <a href="/world/Cast-Profile-Contract.html">인물 카드 계약</a>을 따른다. <code>근위</code>·<code>돌격</code>·<code>궁수</code> 없음. 제식 소화기 모델명 없음.</p><p>다시 뽑을 때:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python tools/cast/generate_nemotron_roster.py --parquet E:\\git\\huggingface\\datasets\\nvidia\\Nemotron-Personas-Korea\\train-00000.parquet --pools docs/game-logic/name-pools --existing docs/game-logic/name-pools/existing-names.json --out docs/game-logic/name-pools/roster-100.json --n 100 --seed 90421</span></span></code></pre></div>`,14)])])}const m=s(n,[["render",i]]);export{g as __pageData,m as default};
